    ]);
    assert.ok(output.includes('navigationId: NAV_1'));
  });

  test('runs scan subcommand in default toon mode', async () => {
    const fixturesDir = path.resolve(import.meta.dirname, 'fixtures');
    const output = await captureCliOutput([
      'node',
      'trace-engine-cli',
      'scan',
      fixturesDir,
      '--name',
